import{_ as a,o,c as r,a0 as e}from"./chunks/framework.Caz7a20Z.js";const c=JSON.parse('{"title":"PPT 做好了，但汇报算法时我有点心慌","description":"今天把之前两篇论文的 PPT 汇报做好了，跟老师聊到之前的一种算法时有点心虚——其实我自己也不太了解，唉先这样吧，明天再跟老师正式汇报。","frontmatter":{"title":"PPT 做好了，但汇报算法时我有点心慌","date":"2026-09-06T00:00:00.000Z","tags":["日记"],"description":"今天把之前两篇论文的 PPT 汇报做好了，跟老师聊到之前的一种算法时有点心虚——其实我自己也不太了解，唉先这样吧，明天再跟老师正式汇报。"},"headers":[],"relativePath":"posts/diary-20260906.md","filePath":"posts/diary-20260906.md","lastUpdated":1788738304000}'),p={name:"posts/diary-20260906.md"};function s(n,t,i,d,l,P){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="ppt-做好了-但汇报算法时我有点心慌" tabindex="-1">PPT 做好了，但汇报算法时我有点心慌 <a class="header-anchor" href="#ppt-做好了-但汇报算法时我有点心慌" aria-label="Permalink to &quot;PPT 做好了，但汇报算法时我有点心慌&quot;">​</a></h1><p>今天周日，活儿干了不少，但心情有点复杂 😅。</p><h2 id="两篇论文的-ppt-做好了" tabindex="-1">两篇论文的 PPT：做好了 <a class="header-anchor" href="#两篇论文的-ppt-做好了" aria-label="Permalink to &quot;两篇论文的 PPT：做好了&quot;">​</a></h2><p>先把成果摆出来：<strong>之前那两篇论文的 PPT 汇报，今天做好了</strong> ✅。</p><p>把论文里的东西压成几页能讲清楚的片子，主线、数据、结果、结论，一节节排下来。做完翻一遍，还挺像那么回事的——至少&quot;有东西可讲&quot;这件事是稳了。</p><h2 id="跟老师汇报算法-有点心慌" tabindex="-1">跟老师汇报算法：有点心慌 <a class="header-anchor" href="#跟老师汇报算法-有点心慌" aria-label="Permalink to &quot;跟老师汇报算法：有点心慌&quot;">​</a></h2><p>然后，<strong>跟老师汇报了之前的一种算法</strong>……哈哈，说实话，<strong>说得我有点心慌</strong> 😬。</p><p><strong>靠，其实我也不太了解的。</strong></p><p>老师一追问细节，我就开始在脑子里现编——这个参数为什么这么设、那一步的原理是什么，我能说出个大概，但真要往深了挖，我自己心里是虚的。那种&quot;嘴上在讲、心里打鼓&quot;的感觉，太难受了。</p><p>讲完出来，就一个念头：<strong>这玩意儿我得真搞懂，不能只会用</strong>。会用和懂，中间隔着的不是一星半点。今天这一课算是被老师无意间给上了一课。</p><h2 id="唉-先这样吧" tabindex="-1">唉，先这样吧 <a class="header-anchor" href="#唉-先这样吧" aria-label="Permalink to &quot;唉，先这样吧&quot;">​</a></h2><p><strong>唉，先这样吧。</strong></p><p>心慌归心慌，今天的 PPT 是实打实做出来的，明天要讲的东西也算有了底。至于那个没吃透的算法，记在账上——回头找时间老老实实啃一遍原理，不能总靠&quot;用得顺手&quot;混过去。</p><p>科研这事儿，蒙混过关一次，迟早还得补回来。</p><h2 id="明天-跟老师汇报" tabindex="-1">明天：跟老师汇报 <a class="header-anchor" href="#明天-跟老师汇报" aria-label="Permalink to &quot;明天：跟老师汇报&quot;">​</a></h2><p><strong>明天跟老师汇报吧</strong> 📊。</p><p>把这两篇论文的 PPT 正式过一遍。今晚争取再顺顺讲稿，把可能被问到的点提前想想，别再出现今天这种&quot;讲到一半发虚&quot;的情况。</p><p>有点紧张，但也还好——至少片子是齐的，故事是通的。明天硬着头皮上，加油 💪！</p>',18)])])}const u=a(p,[["render",s]]);export{c as __pageData,u as default};
